def clean(text):
    changes=[]
    for old,new in EDITS.items():
        if old in text:
            changes.append({'old':old,'new':new,'occurrences':text.count(old)})
            text=text.replace(old,new)
    flag='*Рабочая исследовательская редакция.*\n\n'
    if flag in text:
        changes.append({'old':flag.strip(),'new':'','reason':'Chapter reviewed and integrated; release status is documented globally'})
        text=text.replace(flag,'')
    return text,changes
